with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'كيمياء الغلاف الجوي وجودة الهواء المتقدمة','التفاعلات الضوئية والأوزون والهباء والجسيمات والترسيب وانتشار الملوثات وتكامل الرصد الكيميائي والجوي.',54,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الكيمياء الجوية والهباء',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التلوث الجوي والتطبيقات البيئية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('atmospheric-chemistry-foundations','أسس الكيمياء الجوية','الغازات والتفاعلات والتحولات الكيميائية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تدرس الكيمياء الجوية تركيب الغلاف الجوي وتفاعلات الغازات والجسيمات ومصادرها ومصارفها. تتغير التراكيز بفعل الانبعاثات والنقل والخلط والترسيب والتفاعلات الضوئية، لذلك يرتبط التركيب الكيميائي ارتباطاً وثيقاً بالأحوال الجوية."},{"type":"heading","text":"العوامل الجوية والكيميائية"},{"type":"text","text":"يتأثر أسس الكيمياء الجوية بمصادر الانبعاث والنقل الأفقي والخلط الرأسي والاستقرار والرطوبة والإشعاع ودرجة الحرارة. ينبغي التمييز بين التركيز المقاس قرب السطح والكمية الموجودة في عمود الغلاف الجوي، وبين المادة الأولية والنواتج الثانوية."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد الملوث أو الجسيم ومصدر البيانات وطريقة القياس.","راجع المعايرة والوحدات وفترة المتوسط وأعلام الجودة.","اربط التغيرات الزمنية بالرياح وارتفاع الخلط والاستقرار.","افحص مؤشرات التحول الكيميائي والنقل والترسيب.","قارن بمحطات خلفية أو منتجات مستقلة قبل إسناد المصدر."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حلقة تلوث","text":"اجمع قياسات الملوثات والطقس خلال حلقة زمنية وطبق إطار أسس الكيمياء الجوية. افصل أثر الانبعاثات عن أثر الطقس، ثم حدد ما يمكن إثباته من البيانات وما يحتاج إلى قياسات كيميائية إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ارسم مخططاً يوضح مصادر ومصارف ملوث جوي تختاره."},{"type":"heading","text":"قيود ومصادر خطأ"},{"type":"list","items":["استنتاج المصدر من تركيز ملوث واحد فقط.","تجاهل زمن المتوسط وموقع جهاز القياس.","الخلط بين التزامن الزمني والسببية الكيميائية.","إهمال الرطوبة وتأثيرها في القياسات البصرية.","تعميم نتائج محطة واحدة على منطقة واسعة."]},{"type":"callout","text":"التفسير المتين لجودة الهواء يجمع بين قياس الملوثات وبيانات الطقس والسياق الكيميائي، ولا يعتمد على مؤشر إجمالي وحده."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد أسس الكيمياء الجوية على تفسير تغير تركيب الغلاف الجوي وربط مصادر المواد وانتقالها وتحولها وإزالتها بالظروف الجوية."}]}'::jsonb,6960,50,'["شرح أساسيات أسس الكيمياء الجوية","تحليل أثر الطقس في التركيب الجوي","تقييم البيانات وحدود الاستنتاج"]'::jsonb,'الكيمياء الجوية والهباء'),
('photochemical-reactions-atmosphere','التفاعلات الكيميائية الضوئية','دور الإشعاع الشمسي في تكوين الملوثات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تبدأ تفاعلات ضوئية عندما تمتص الجزيئات فوتونات ذات طاقة مناسبة فتتفكك أو تدخل مسارات تفاعلية. تتحكم شدة الإشعاع والكتلة الهوائية ودرجة الحرارة وتوافر المتفاعلات في معدلات التكوين."},{"type":"heading","text":"العوامل الجوية والكيميائية"},{"type":"text","text":"يتأثر التفاعلات الكيميائية الضوئية بمصادر الانبعاث والنقل الأفقي والخلط الرأسي والاستقرار والرطوبة والإشعاع ودرجة الحرارة. ينبغي التمييز بين التركيز المقاس قرب السطح والكمية الموجودة في عمود الغلاف الجوي، وبين المادة الأولية والنواتج الثانوية."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد الملوث أو الجسيم ومصدر البيانات وطريقة القياس.","راجع المعايرة والوحدات وفترة المتوسط وأعلام الجودة.","اربط التغيرات الزمنية بالرياح وارتفاع الخلط والاستقرار.","افحص مؤشرات التحول الكيميائي والنقل والترسيب.","قارن بمحطات خلفية أو منتجات مستقلة قبل إسناد المصدر."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حلقة تلوث","text":"اجمع قياسات الملوثات والطقس خلال حلقة زمنية وطبق إطار التفاعلات الكيميائية الضوئية. افصل أثر الانبعاثات عن أثر الطقس، ثم حدد ما يمكن إثباته من البيانات وما يحتاج إلى قياسات كيميائية إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر كيف يمكن أن يؤدي ازدياد الإشعاع إلى تغير إنتاج الأوزون قرب السطح."},{"type":"heading","text":"قيود ومصادر خطأ"},{"type":"list","items":["استنتاج المصدر من تركيز ملوث واحد فقط.","تجاهل زمن المتوسط وموقع جهاز القياس.","الخلط بين التزامن الزمني والسببية الكيميائية.","إهمال الرطوبة وتأثيرها في القياسات البصرية.","تعميم نتائج محطة واحدة على منطقة واسعة."]},{"type":"callout","text":"التفسير المتين لجودة الهواء يجمع بين قياس الملوثات وبيانات الطقس والسياق الكيميائي، ولا يعتمد على مؤشر إجمالي وحده."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد التفاعلات الكيميائية الضوئية على تفسير تغير تركيب الغلاف الجوي وربط مصادر المواد وانتقالها وتحولها وإزالتها بالظروف الجوية."}]}'::jsonb,6970,50,'["شرح أساسيات التفاعلات الكيميائية الضوئية","تحليل أثر الطقس في التركيب الجوي","تقييم البيانات وحدود الاستنتاج"]'::jsonb,'الكيمياء الجوية والهباء'),
('tropospheric-ozone-formation','تكوّن الأوزون التروبوسفيري','تفاعلات أكاسيد النيتروجين والمركبات العضوية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتكون الأوزون قرب السطح عبر كيمياء ضوئية معقدة تشمل أكاسيد النيتروجين والمركبات العضوية المتطايرة وأشعة الشمس. تختلف استجابة الأوزون لنسب المتفاعلات، وقد تكون محدودة بالمواد العضوية أو بأكاسيد النيتروجين حسب البيئة."},{"type":"heading","text":"العوامل الجوية والكيميائية"},{"type":"text","text":"يتأثر تكوّن الأوزون التروبوسفيري بمصادر الانبعاث والنقل الأفقي والخلط الرأسي والاستقرار والرطوبة والإشعاع ودرجة الحرارة. ينبغي التمييز بين التركيز المقاس قرب السطح والكمية الموجودة في عمود الغلاف الجوي، وبين المادة الأولية والنواتج الثانوية."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد الملوث أو الجسيم ومصدر البيانات وطريقة القياس.","راجع المعايرة والوحدات وفترة المتوسط وأعلام الجودة.","اربط التغيرات الزمنية بالرياح وارتفاع الخلط والاستقرار.","افحص مؤشرات التحول الكيميائي والنقل والترسيب.","قارن بمحطات خلفية أو منتجات مستقلة قبل إسناد المصدر."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حلقة تلوث","text":"اجمع قياسات الملوثات والطقس خلال حلقة زمنية وطبق إطار تكوّن الأوزون التروبوسفيري. افصل أثر الانبعاثات عن أثر الطقس، ثم حدد ما يمكن إثباته من البيانات وما يحتاج إلى قياسات كيميائية إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن بيئة حضرية محدودة بأكاسيد النيتروجين مع بيئة غنية بها من حيث استجابة الأوزون."},{"type":"heading","text":"قيود ومصادر خطأ"},{"type":"list","items":["استنتاج المصدر من تركيز ملوث واحد فقط.","تجاهل زمن المتوسط وموقع جهاز القياس.","الخلط بين التزامن الزمني والسببية الكيميائية.","إهمال الرطوبة وتأثيرها في القياسات البصرية.","تعميم نتائج محطة واحدة على منطقة واسعة."]},{"type":"callout","text":"التفسير المتين لجودة الهواء يجمع بين قياس الملوثات وبيانات الطقس والسياق الكيميائي، ولا يعتمد على مؤشر إجمالي وحده."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد تكوّن الأوزون التروبوسفيري على تفسير تغير تركيب الغلاف الجوي وربط مصادر المواد وانتقالها وتحولها وإزالتها بالظروف الجوية."}]}'::jsonb,6980,50,'["شرح أساسيات تكوّن الأوزون التروبوسفيري","تحليل أثر الطقس في التركيب الجوي","تقييم البيانات وحدود الاستنتاج"]'::jsonb,'الكيمياء الجوية والهباء'),
('nitrogen-oxides-atmospheric-cycle','دورة أكاسيد النيتروجين الجوية','الانبعاثات والتحول والترسيب','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تنبعث أكاسيد النيتروجين من مصادر احتراق طبيعية وبشرية، وتتحول كيميائياً إلى أنواع أخرى وتشارك في تكوين الأوزون والنترات. يتأثر توزيعها بمصادر الانبعاث وارتفاع الخلط والرياح والإشعاع."},{"type":"heading","text":"العوامل الجوية والكيميائية"},{"type":"text","text":"يتأثر دورة أكاسيد النيتروجين الجوية بمصادر الانبعاث والنقل الأفقي والخلط الرأسي والاستقرار والرطوبة والإشعاع ودرجة الحرارة. ينبغي التمييز بين التركيز المقاس قرب السطح والكمية الموجودة في عمود الغلاف الجوي، وبين المادة الأولية والنواتج الثانوية."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد الملوث أو الجسيم ومصدر البيانات وطريقة القياس.","راجع المعايرة والوحدات وفترة المتوسط وأعلام الجودة.","اربط التغيرات الزمنية بالرياح وارتفاع الخلط والاستقرار.","افحص مؤشرات التحول الكيميائي والنقل والترسيب.","قارن بمحطات خلفية أو منتجات مستقلة قبل إسناد المصدر."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حلقة تلوث","text":"اجمع قياسات الملوثات والطقس خلال حلقة زمنية وطبق إطار دورة أكاسيد النيتروجين الجوية. افصل أثر الانبعاثات عن أثر الطقس، ثم حدد ما يمكن إثباته من البيانات وما يحتاج إلى قياسات كيميائية إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد مسارات انتقال NOx من مصدر حضري إلى مكونات كيميائية ثانوية."},{"type":"heading","text":"قيود ومصادر خطأ"},{"type":"list","items":["استنتاج المصدر من تركيز ملوث واحد فقط.","تجاهل زمن المتوسط وموقع جهاز القياس.","الخلط بين التزامن الزمني والسببية الكيميائية.","إهمال الرطوبة وتأثيرها في القياسات البصرية.","تعميم نتائج محطة واحدة على منطقة واسعة."]},{"type":"callout","text":"التفسير المتين لجودة الهواء يجمع بين قياس الملوثات وبيانات الطقس والسياق الكيميائي، ولا يعتمد على مؤشر إجمالي وحده."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد دورة أكاسيد النيتروجين الجوية على تفسير تغير تركيب الغلاف الجوي وربط مصادر المواد وانتقالها وتحولها وإزالتها بالظروف الجوية."}]}'::jsonb,6990,50,'["شرح أساسيات دورة أكاسيد النيتروجين الجوية","تحليل أثر الطقس في التركيب الجوي","تقييم البيانات وحدود الاستنتاج"]'::jsonb,'الكيمياء الجوية والهباء'),
('volatile-organic-compounds','المركبات العضوية المتطايرة','مصادرها وتفاعلاتها الجوية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تشمل المركبات العضوية المتطايرة طيفاً واسعاً من المركبات الطبيعية والصناعية، وتشارك في تكوين الأوزون والهباء العضوي الثانوي. تختلف تفاعليتها وأعمارها الجوية اختلافاً كبيراً."},{"type":"heading","text":"العوامل الجوية والكيميائية"},{"type":"text","text":"يتأثر المركبات العضوية المتطايرة بمصادر الانبعاث والنقل الأفقي والخلط الرأسي والاستقرار والرطوبة والإشعاع ودرجة الحرارة. ينبغي التمييز بين التركيز المقاس قرب السطح والكمية الموجودة في عمود الغلاف الجوي، وبين المادة الأولية والنواتج الثانوية."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد الملوث أو الجسيم ومصدر البيانات وطريقة القياس.","راجع المعايرة والوحدات وفترة المتوسط وأعلام الجودة.","اربط التغيرات الزمنية بالرياح وارتفاع الخلط والاستقرار.","افحص مؤشرات التحول الكيميائي والنقل والترسيب.","قارن بمحطات خلفية أو منتجات مستقلة قبل إسناد المصدر."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حلقة تلوث","text":"اجمع قياسات الملوثات والطقس خلال حلقة زمنية وطبق إطار المركبات العضوية المتطايرة. افصل أثر الانبعاثات عن أثر الطقس، ثم حدد ما يمكن إثباته من البيانات وما يحتاج إلى قياسات كيميائية إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صنف مصادر المركبات العضوية المتطايرة إلى طبيعية وبشرية وناقش اختلاف التفاعلية."},{"type":"heading","text":"قيود ومصادر خطأ"},{"type":"list","items":["استنتاج المصدر من تركيز ملوث واحد فقط.","تجاهل زمن المتوسط وموقع جهاز القياس.","الخلط بين التزامن الزمني والسببية الكيميائية.","إهمال الرطوبة وتأثيرها في القياسات البصرية.","تعميم نتائج محطة واحدة على منطقة واسعة."]},{"type":"callout","text":"التفسير المتين لجودة الهواء يجمع بين قياس الملوثات وبيانات الطقس والسياق الكيميائي، ولا يعتمد على مؤشر إجمالي وحده."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد المركبات العضوية المتطايرة على تفسير تغير تركيب الغلاف الجوي وربط مصادر المواد وانتقالها وتحولها وإزالتها بالظروف الجوية."}]}'::jsonb,7000,50,'["شرح أساسيات المركبات العضوية المتطايرة","تحليل أثر الطقس في التركيب الجوي","تقييم البيانات وحدود الاستنتاج"]'::jsonb,'الكيمياء الجوية والهباء'),
('sulfur-chemistry-atmosphere','كيمياء الكبريت في الغلاف الجوي','ثاني أكسيد الكبريت والكبريتات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتأكسد ثاني أكسيد الكبريت في الطور الغازي أو داخل قطرات السحب ليشكل مركبات كبريتية مثل الكبريتات. تؤثر الرطوبة والسحب والمؤكسدات على سرعة التحول وحجم الجسيمات الناتجة."},{"type":"heading","text":"العوامل الجوية والكيميائية"},{"type":"text","text":"يتأثر كيمياء الكبريت في الغلاف الجوي بمصادر الانبعاث والنقل الأفقي والخلط الرأسي والاستقرار والرطوبة والإشعاع ودرجة الحرارة. ينبغي التمييز بين التركيز المقاس قرب السطح والكمية الموجودة في عمود الغلاف الجوي، وبين المادة الأولية والنواتج الثانوية."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد الملوث أو الجسيم ومصدر البيانات وطريقة القياس.","راجع المعايرة والوحدات وفترة المتوسط وأعلام الجودة.","اربط التغيرات الزمنية بالرياح وارتفاع الخلط والاستقرار.","افحص مؤشرات التحول الكيميائي والنقل والترسيب.","قارن بمحطات خلفية أو منتجات مستقلة قبل إسناد المصدر."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حلقة تلوث","text":"اجمع قياسات الملوثات والطقس خلال حلقة زمنية وطبق إطار كيمياء الكبريت في الغلاف الجوي. افصل أثر الانبعاثات عن أثر الطقس، ثم حدد ما يمكن إثباته من البيانات وما يحتاج إلى قياسات كيميائية إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح الفرق بين أكسدة SO2 في الطور الغازي وأكسدته داخل السحب."},{"type":"heading","text":"قيود ومصادر خطأ"},{"type":"list","items":["استنتاج المصدر من تركيز ملوث واحد فقط.","تجاهل زمن المتوسط وموقع جهاز القياس.","الخلط بين التزامن الزمني والسببية الكيميائية.","إهمال الرطوبة وتأثيرها في القياسات البصرية.","تعميم نتائج محطة واحدة على منطقة واسعة."]},{"type":"callout","text":"التفسير المتين لجودة الهواء يجمع بين قياس الملوثات وبيانات الطقس والسياق الكيميائي، ولا يعتمد على مؤشر إجمالي وحده."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد كيمياء الكبريت في الغلاف الجوي على تفسير تغير تركيب الغلاف الجوي وربط مصادر المواد وانتقالها وتحولها وإزالتها بالظروف الجوية."}]}'::jsonb,7010,50,'["شرح أساسيات كيمياء الكبريت في الغلاف الجوي","تحليل أثر الطقس في التركيب الجوي","تقييم البيانات وحدود الاستنتاج"]'::jsonb,'الكيمياء الجوية والهباء'),
('secondary-organic-aerosol','الهباء العضوي الثانوي','تكون الجسيمات من أكسدة المركبات العضوية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتكون الهباء العضوي الثانوي عندما تتحول نواتج أكسدة المركبات العضوية إلى مواد منخفضة التطاير تتكاثف أو تتشكل جسيمات جديدة. يعتمد المردود على نوع المركب والمؤكسدات والحرارة والرطوبة."},{"type":"heading","text":"العوامل الجوية والكيميائية"},{"type":"text","text":"يتأثر الهباء العضوي الثانوي بمصادر الانبعاث والنقل الأفقي والخلط الرأسي والاستقرار والرطوبة والإشعاع ودرجة الحرارة. ينبغي التمييز بين التركيز المقاس قرب السطح والكمية الموجودة في عمود الغلاف الجوي، وبين المادة الأولية والنواتج الثانوية."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد الملوث أو الجسيم ومصدر البيانات وطريقة القياس.","راجع المعايرة والوحدات وفترة المتوسط وأعلام الجودة.","اربط التغيرات الزمنية بالرياح وارتفاع الخلط والاستقرار.","افحص مؤشرات التحول الكيميائي والنقل والترسيب.","قارن بمحطات خلفية أو منتجات مستقلة قبل إسناد المصدر."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حلقة تلوث","text":"اجمع قياسات الملوثات والطقس خلال حلقة زمنية وطبق إطار الهباء العضوي الثانوي. افصل أثر الانبعاثات عن أثر الطقس، ثم حدد ما يمكن إثباته من البيانات وما يحتاج إلى قياسات كيميائية إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"وضح كيف يمكن لتغير درجة الحرارة أن يؤثر في انتقال نواتج الأكسدة إلى الطور الجسيمي."},{"type":"heading","text":"قيود ومصادر خطأ"},{"type":"list","items":["استنتاج المصدر من تركيز ملوث واحد فقط.","تجاهل زمن المتوسط وموقع جهاز القياس.","الخلط بين التزامن الزمني والسببية الكيميائية.","إهمال الرطوبة وتأثيرها في القياسات البصرية.","تعميم نتائج محطة واحدة على منطقة واسعة."]},{"type":"callout","text":"التفسير المتين لجودة الهواء يجمع بين قياس الملوثات وبيانات الطقس والسياق الكيميائي، ولا يعتمد على مؤشر إجمالي وحده."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد الهباء العضوي الثانوي على تفسير تغير تركيب الغلاف الجوي وربط مصادر المواد وانتقالها وتحولها وإزالتها بالظروف الجوية."}]}'::jsonb,7020,50,'["شرح أساسيات الهباء العضوي الثانوي","تحليل أثر الطقس في التركيب الجوي","تقييم البيانات وحدود الاستنتاج"]'::jsonb,'الكيمياء الجوية والهباء'),
('particulate-matter-size-distributions','توزيعات أحجام الجسيمات','الأنماط الدقيقة والخشنة وفائقة الدقة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"توزيع أحجام الجسيمات يصف عددها أو كتلتها بحسب القطر، ويرتبط بمصدرها وآليات التكوين والنمو والإزالة. لا تكفي قيمة PM2.5 الكتلية وحدها لفهم العدد أو التركيب الكيميائي."},{"type":"heading","text":"العوامل الجوية والكيميائية"},{"type":"text","text":"يتأثر توزيعات أحجام الجسيمات بمصادر الانبعاث والنقل الأفقي والخلط الرأسي والاستقرار والرطوبة والإشعاع ودرجة الحرارة. ينبغي التمييز بين التركيز المقاس قرب السطح والكمية الموجودة في عمود الغلاف الجوي، وبين المادة الأولية والنواتج الثانوية."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد الملوث أو الجسيم ومصدر البيانات وطريقة القياس.","راجع المعايرة والوحدات وفترة المتوسط وأعلام الجودة.","اربط التغيرات الزمنية بالرياح وارتفاع الخلط والاستقرار.","افحص مؤشرات التحول الكيميائي والنقل والترسيب.","قارن بمحطات خلفية أو منتجات مستقلة قبل إسناد المصدر."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حلقة تلوث","text":"اجمع قياسات الملوثات والطقس خلال حلقة زمنية وطبق إطار توزيعات أحجام الجسيمات. افصل أثر الانبعاثات عن أثر الطقس، ثم حدد ما يمكن إثباته من البيانات وما يحتاج إلى قياسات كيميائية إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن بين توزيع عددي وتوزيع كتلي للجسيمات ووضح اختلاف دلالتهما."},{"type":"heading","text":"قيود ومصادر خطأ"},{"type":"list","items":["استنتاج المصدر من تركيز ملوث واحد فقط.","تجاهل زمن المتوسط وموقع جهاز القياس.","الخلط بين التزامن الزمني والسببية الكيميائية.","إهمال الرطوبة وتأثيرها في القياسات البصرية.","تعميم نتائج محطة واحدة على منطقة واسعة."]},{"type":"callout","text":"التفسير المتين لجودة الهواء يجمع بين قياس الملوثات وبيانات الطقس والسياق الكيميائي، ولا يعتمد على مؤشر إجمالي وحده."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد توزيعات أحجام الجسيمات على تفسير تغير تركيب الغلاف الجوي وربط مصادر المواد وانتقالها وتحولها وإزالتها بالظروف الجوية."}]}'::jsonb,7030,50,'["شرح أساسيات توزيعات أحجام الجسيمات","تحليل أثر الطقس في التركيب الجوي","تقييم البيانات وحدود الاستنتاج"]'::jsonb,'الكيمياء الجوية والهباء'),
('aerosol-hygroscopic-growth','النمو الاسترطابي للهباء','امتصاص الماء وتأثير الرطوبة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تمتص بعض الجسيمات الماء عند ارتفاع الرطوبة النسبية فيزداد قطرها وتتغير خصائصها البصرية والكتلية الظاهرية. يعتمد النمو على التركيب الكيميائي والحجم وتاريخ الرطوبة."},{"type":"heading","text":"العوامل الجوية والكيميائية"},{"type":"text","text":"يتأثر النمو الاسترطابي للهباء بمصادر الانبعاث والنقل الأفقي والخلط الرأسي والاستقرار والرطوبة والإشعاع ودرجة الحرارة. ينبغي التمييز بين التركيز المقاس قرب السطح والكمية الموجودة في عمود الغلاف الجوي، وبين المادة الأولية والنواتج الثانوية."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد الملوث أو الجسيم ومصدر البيانات وطريقة القياس.","راجع المعايرة والوحدات وفترة المتوسط وأعلام الجودة.","اربط التغيرات الزمنية بالرياح وارتفاع الخلط والاستقرار.","افحص مؤشرات التحول الكيميائي والنقل والترسيب.","قارن بمحطات خلفية أو منتجات مستقلة قبل إسناد المصدر."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حلقة تلوث","text":"اجمع قياسات الملوثات والطقس خلال حلقة زمنية وطبق إطار النمو الاسترطابي للهباء. افصل أثر الانبعاثات عن أثر الطقس، ثم حدد ما يمكن إثباته من البيانات وما يحتاج إلى قياسات كيميائية إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح لماذا قد ترتفع قراءة جهاز جسيمات بصري عند زيادة الرطوبة دون زيادة مماثلة في كتلة الجسيمات الجافة."},{"type":"heading","text":"قيود ومصادر خطأ"},{"type":"list","items":["استنتاج المصدر من تركيز ملوث واحد فقط.","تجاهل زمن المتوسط وموقع جهاز القياس.","الخلط بين التزامن الزمني والسببية الكيميائية.","إهمال الرطوبة وتأثيرها في القياسات البصرية.","تعميم نتائج محطة واحدة على منطقة واسعة."]},{"type":"callout","text":"التفسير المتين لجودة الهواء يجمع بين قياس الملوثات وبيانات الطقس والسياق الكيميائي، ولا يعتمد على مؤشر إجمالي وحده."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد النمو الاسترطابي للهباء على تفسير تغير تركيب الغلاف الجوي وربط مصادر المواد وانتقالها وتحولها وإزالتها بالظروف الجوية."}]}'::jsonb,7040,50,'["شرح أساسيات النمو الاسترطابي للهباء","تحليل أثر الطقس في التركيب الجوي","تقييم البيانات وحدود الاستنتاج"]'::jsonb,'الكيمياء الجوية والهباء'),
('aerosol-cloud-interactions','تفاعلات الهباء والسحب','نوى التكاثف وخصائص القطرات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تؤثر الجسيمات في تكوين قطرات السحب عبر عمل بعضها كنوى تكاثف، وقد تغير عدد القطرات وحجمها وخصائص السحب. تتوقف الاستجابة على وفرة الجسيمات وتوزيع الأحجام والرطوبة الصاعدة وخصائص السحب."},{"type":"heading","text":"العوامل الجوية والكيميائية"},{"type":"text","text":"يتأثر تفاعلات الهباء والسحب بمصادر الانبعاث والنقل الأفقي والخلط الرأسي والاستقرار والرطوبة والإشعاع ودرجة الحرارة. ينبغي التمييز بين التركيز المقاس قرب السطح والكمية الموجودة في عمود الغلاف الجوي، وبين المادة الأولية والنواتج الثانوية."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد الملوث أو الجسيم ومصدر البيانات وطريقة القياس.","راجع المعايرة والوحدات وفترة المتوسط وأعلام الجودة.","اربط التغيرات الزمنية بالرياح وارتفاع الخلط والاستقرار.","افحص مؤشرات التحول الكيميائي والنقل والترسيب.","قارن بمحطات خلفية أو منتجات مستقلة قبل إسناد المصدر."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حلقة تلوث","text":"اجمع قياسات الملوثات والطقس خلال حلقة زمنية وطبق إطار تفاعلات الهباء والسحب. افصل أثر الانبعاثات عن أثر الطقس، ثم حدد ما يمكن إثباته من البيانات وما يحتاج إلى قياسات كيميائية إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ناقش كيف يمكن لتغير تركيز نوى التكاثف أن يغير توزيع أحجام قطرات السحب."},{"type":"heading","text":"قيود ومصادر خطأ"},{"type":"list","items":["استنتاج المصدر من تركيز ملوث واحد فقط.","تجاهل زمن المتوسط وموقع جهاز القياس.","الخلط بين التزامن الزمني والسببية الكيميائية.","إهمال الرطوبة وتأثيرها في القياسات البصرية.","تعميم نتائج محطة واحدة على منطقة واسعة."]},{"type":"callout","text":"التفسير المتين لجودة الهواء يجمع بين قياس الملوثات وبيانات الطقس والسياق الكيميائي، ولا يعتمد على مؤشر إجمالي وحده."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد تفاعلات الهباء والسحب على تفسير تغير تركيب الغلاف الجوي وربط مصادر المواد وانتقالها وتحولها وإزالتها بالظروف الجوية."}]}'::jsonb,7050,50,'["شرح أساسيات تفاعلات الهباء والسحب","تحليل أثر الطقس في التركيب الجوي","تقييم البيانات وحدود الاستنتاج"]'::jsonb,'الكيمياء الجوية والهباء'),
('cloud-condensation-nuclei-measurement','قياس نوى تكاثف السحب','التركيز والاستجابة للتشبع الفائق','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تقاس نوى تكاثف السحب عند قيم محددة من التشبع الفائق، لذلك ترتبط النتيجة بشرط القياس ولا تمثل عدداً ثابتاً مستقلاً عن الظروف. يلزم توثيق إعداد الجهاز ومعايرته ومجال حجم الجسيمات."},{"type":"heading","text":"العوامل الجوية والكيميائية"},{"type":"text","text":"يتأثر قياس نوى تكاثف السحب بمصادر الانبعاث والنقل الأفقي والخلط الرأسي والاستقرار والرطوبة والإشعاع ودرجة الحرارة. ينبغي التمييز بين التركيز المقاس قرب السطح والكمية الموجودة في عمود الغلاف الجوي، وبين المادة الأولية والنواتج الثانوية."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد الملوث أو الجسيم ومصدر البيانات وطريقة القياس.","راجع المعايرة والوحدات وفترة المتوسط وأعلام الجودة.","اربط التغيرات الزمنية بالرياح وارتفاع الخلط والاستقرار.","افحص مؤشرات التحول الكيميائي والنقل والترسيب.","قارن بمحطات خلفية أو منتجات مستقلة قبل إسناد المصدر."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حلقة تلوث","text":"اجمع قياسات الملوثات والطقس خلال حلقة زمنية وطبق إطار قياس نوى تكاثف السحب. افصل أثر الانبعاثات عن أثر الطقس، ثم حدد ما يمكن إثباته من البيانات وما يحتاج إلى قياسات كيميائية إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر لماذا تختلف أعداد CCN المقاسة عند مستويين مختلفين من التشبع الفائق."},{"type":"heading","text":"قيود ومصادر خطأ"},{"type":"list","items":["استنتاج المصدر من تركيز ملوث واحد فقط.","تجاهل زمن المتوسط وموقع جهاز القياس.","الخلط بين التزامن الزمني والسببية الكيميائية.","إهمال الرطوبة وتأثيرها في القياسات البصرية.","تعميم نتائج محطة واحدة على منطقة واسعة."]},{"type":"callout","text":"التفسير المتين لجودة الهواء يجمع بين قياس الملوثات وبيانات الطقس والسياق الكيميائي، ولا يعتمد على مؤشر إجمالي وحده."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد قياس نوى تكاثف السحب على تفسير تغير تركيب الغلاف الجوي وربط مصادر المواد وانتقالها وتحولها وإزالتها بالظروف الجوية."}]}'::jsonb,7060,50,'["شرح أساسيات قياس نوى تكاثف السحب","تحليل أثر الطقس في التركيب الجوي","تقييم البيانات وحدود الاستنتاج"]'::jsonb,'التلوث الجوي والتطبيقات البيئية'),
('atmospheric-deposition-processes','عمليات الترسيب الجوي','الترسيب الجاف والرطب','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تزيل عمليات الترسيب المواد من الغلاف الجوي إلى السطح، إما بالتصادم والالتصاق دون هطول أو بالاحتجاز داخل المطر والثلج والضباب. تختلف كفاءة الإزالة باختلاف حجم الجسيمات وذوبان الغازات والسطح."},{"type":"heading","text":"العوامل الجوية والكيميائية"},{"type":"text","text":"يتأثر عمليات الترسيب الجوي بمصادر الانبعاث والنقل الأفقي والخلط الرأسي والاستقرار والرطوبة والإشعاع ودرجة الحرارة. ينبغي التمييز بين التركيز المقاس قرب السطح والكمية الموجودة في عمود الغلاف الجوي، وبين المادة الأولية والنواتج الثانوية."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد الملوث أو الجسيم ومصدر البيانات وطريقة القياس.","راجع المعايرة والوحدات وفترة المتوسط وأعلام الجودة.","اربط التغيرات الزمنية بالرياح وارتفاع الخلط والاستقرار.","افحص مؤشرات التحول الكيميائي والنقل والترسيب.","قارن بمحطات خلفية أو منتجات مستقلة قبل إسناد المصدر."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حلقة تلوث","text":"اجمع قياسات الملوثات والطقس خلال حلقة زمنية وطبق إطار عمليات الترسيب الجوي. افصل أثر الانبعاثات عن أثر الطقس، ثم حدد ما يمكن إثباته من البيانات وما يحتاج إلى قياسات كيميائية إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن كفاءة الترسيب الجاف والرطب لغاز قابل للذوبان وجسيم خشن."},{"type":"heading","text":"قيود ومصادر خطأ"},{"type":"list","items":["استنتاج المصدر من تركيز ملوث واحد فقط.","تجاهل زمن المتوسط وموقع جهاز القياس.","الخلط بين التزامن الزمني والسببية الكيميائية.","إهمال الرطوبة وتأثيرها في القياسات البصرية.","تعميم نتائج محطة واحدة على منطقة واسعة."]},{"type":"callout","text":"التفسير المتين لجودة الهواء يجمع بين قياس الملوثات وبيانات الطقس والسياق الكيميائي، ولا يعتمد على مؤشر إجمالي وحده."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد عمليات الترسيب الجوي على تفسير تغير تركيب الغلاف الجوي وربط مصادر المواد وانتقالها وتحولها وإزالتها بالظروف الجوية."}]}'::jsonb,7070,50,'["شرح أساسيات عمليات الترسيب الجوي","تحليل أثر الطقس في التركيب الجوي","تقييم البيانات وحدود الاستنتاج"]'::jsonb,'التلوث الجوي والتطبيقات البيئية'),
('acid-deposition-chemistry','كيمياء الترسيب الحمضي','تكوين الأحماض وانتقالها إلى السطح','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينشأ الترسيب الحمضي من تحول مركبات الكبريت والنيتروجين إلى أحماض ومركبات مؤكسدة ثم انتقالها عبر الهطول أو الترسيب الجاف. يتأثر الأثر البيئي بقدرة التربة والمياه على المعادلة والتركيب المحلي."},{"type":"heading","text":"العوامل الجوية والكيميائية"},{"type":"text","text":"يتأثر كيمياء الترسيب الحمضي بمصادر الانبعاث والنقل الأفقي والخلط الرأسي والاستقرار والرطوبة والإشعاع ودرجة الحرارة. ينبغي التمييز بين التركيز المقاس قرب السطح والكمية الموجودة في عمود الغلاف الجوي، وبين المادة الأولية والنواتج الثانوية."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد الملوث أو الجسيم ومصدر البيانات وطريقة القياس.","راجع المعايرة والوحدات وفترة المتوسط وأعلام الجودة.","اربط التغيرات الزمنية بالرياح وارتفاع الخلط والاستقرار.","افحص مؤشرات التحول الكيميائي والنقل والترسيب.","قارن بمحطات خلفية أو منتجات مستقلة قبل إسناد المصدر."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حلقة تلوث","text":"اجمع قياسات الملوثات والطقس خلال حلقة زمنية وطبق إطار كيمياء الترسيب الحمضي. افصل أثر الانبعاثات عن أثر الطقس، ثم حدد ما يمكن إثباته من البيانات وما يحتاج إلى قياسات كيميائية إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح المسار الكيميائي العام من انبعاث SO2 إلى ترسيب الكبريتات الحمضية."},{"type":"heading","text":"قيود ومصادر خطأ"},{"type":"list","items":["استنتاج المصدر من تركيز ملوث واحد فقط.","تجاهل زمن المتوسط وموقع جهاز القياس.","الخلط بين التزامن الزمني والسببية الكيميائية.","إهمال الرطوبة وتأثيرها في القياسات البصرية.","تعميم نتائج محطة واحدة على منطقة واسعة."]},{"type":"callout","text":"التفسير المتين لجودة الهواء يجمع بين قياس الملوثات وبيانات الطقس والسياق الكيميائي، ولا يعتمد على مؤشر إجمالي وحده."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد كيمياء الترسيب الحمضي على تفسير تغير تركيب الغلاف الجوي وربط مصادر المواد وانتقالها وتحولها وإزالتها بالظروف الجوية."}]}'::jsonb,7080,50,'["شرح أساسيات كيمياء الترسيب الحمضي","تحليل أثر الطقس في التركيب الجوي","تقييم البيانات وحدود الاستنتاج"]'::jsonb,'التلوث الجوي والتطبيقات البيئية'),
('urban-heat-air-quality-interaction','تفاعل الجزيرة الحرارية مع جودة الهواء','الخلط والتهوية والكيمياء الحضرية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تؤثر الجزيرة الحرارية الحضرية في الاستقرار والخلط والرياح المحلية، وقد تغير تراكيز الملوثات عبر التهوية والتفاعلات الكيميائية. لا يكون أثر ارتفاع الحرارة على كل ملوث بالاتجاه نفسه."},{"type":"heading","text":"العوامل الجوية والكيميائية"},{"type":"text","text":"يتأثر تفاعل الجزيرة الحرارية مع جودة الهواء بمصادر الانبعاث والنقل الأفقي والخلط الرأسي والاستقرار والرطوبة والإشعاع ودرجة الحرارة. ينبغي التمييز بين التركيز المقاس قرب السطح والكمية الموجودة في عمود الغلاف الجوي، وبين المادة الأولية والنواتج الثانوية."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد الملوث أو الجسيم ومصدر البيانات وطريقة القياس.","راجع المعايرة والوحدات وفترة المتوسط وأعلام الجودة.","اربط التغيرات الزمنية بالرياح وارتفاع الخلط والاستقرار.","افحص مؤشرات التحول الكيميائي والنقل والترسيب.","قارن بمحطات خلفية أو منتجات مستقلة قبل إسناد المصدر."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حلقة تلوث","text":"اجمع قياسات الملوثات والطقس خلال حلقة زمنية وطبق إطار تفاعل الجزيرة الحرارية مع جودة الهواء. افصل أثر الانبعاثات عن أثر الطقس، ثم حدد ما يمكن إثباته من البيانات وما يحتاج إلى قياسات كيميائية إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل سيناريو مدينة ساكنة الرياح مع موجة حر ووضح العوامل المؤثرة في جودة الهواء."},{"type":"heading","text":"قيود ومصادر خطأ"},{"type":"list","items":["استنتاج المصدر من تركيز ملوث واحد فقط.","تجاهل زمن المتوسط وموقع جهاز القياس.","الخلط بين التزامن الزمني والسببية الكيميائية.","إهمال الرطوبة وتأثيرها في القياسات البصرية.","تعميم نتائج محطة واحدة على منطقة واسعة."]},{"type":"callout","text":"التفسير المتين لجودة الهواء يجمع بين قياس الملوثات وبيانات الطقس والسياق الكيميائي، ولا يعتمد على مؤشر إجمالي وحده."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد تفاعل الجزيرة الحرارية مع جودة الهواء على تفسير تغير تركيب الغلاف الجوي وربط مصادر المواد وانتقالها وتحولها وإزالتها بالظروف الجوية."}]}'::jsonb,7090,50,'["شرح أساسيات تفاعل الجزيرة الحرارية مع جودة الهواء","تحليل أثر الطقس في التركيب الجوي","تقييم البيانات وحدود الاستنتاج"]'::jsonb,'التلوث الجوي والتطبيقات البيئية'),
('boundary-layer-pollutant-dispersion','انتشار الملوثات في الطبقة الحدية','الخلط الرأسي والقص والاستقرار','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتحكم ارتفاع الطبقة الحدية والاستقرار والاضطراب والرياح في تخفيف الملوثات ونقلها. قد يؤدي الانقلاب الحراري إلى حصر الملوثات قرب السطح، بينما يعزز الخلط العميق التشتت الرأسي."},{"type":"heading","text":"العوامل الجوية والكيميائية"},{"type":"text","text":"يتأثر انتشار الملوثات في الطبقة الحدية بمصادر الانبعاث والنقل الأفقي والخلط الرأسي والاستقرار والرطوبة والإشعاع ودرجة الحرارة. ينبغي التمييز بين التركيز المقاس قرب السطح والكمية الموجودة في عمود الغلاف الجوي، وبين المادة الأولية والنواتج الثانوية."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد الملوث أو الجسيم ومصدر البيانات وطريقة القياس.","راجع المعايرة والوحدات وفترة المتوسط وأعلام الجودة.","اربط التغيرات الزمنية بالرياح وارتفاع الخلط والاستقرار.","افحص مؤشرات التحول الكيميائي والنقل والترسيب.","قارن بمحطات خلفية أو منتجات مستقلة قبل إسناد المصدر."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حلقة تلوث","text":"اجمع قياسات الملوثات والطقس خلال حلقة زمنية وطبق إطار انتشار الملوثات في الطبقة الحدية. افصل أثر الانبعاثات عن أثر الطقس، ثم حدد ما يمكن إثباته من البيانات وما يحتاج إلى قياسات كيميائية إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن تطور تركيز ملوث قرب السطح في يوم مستقر ويوم مختلط جيداً."},{"type":"heading","text":"قيود ومصادر خطأ"},{"type":"list","items":["استنتاج المصدر من تركيز ملوث واحد فقط.","تجاهل زمن المتوسط وموقع جهاز القياس.","الخلط بين التزامن الزمني والسببية الكيميائية.","إهمال الرطوبة وتأثيرها في القياسات البصرية.","تعميم نتائج محطة واحدة على منطقة واسعة."]},{"type":"callout","text":"التفسير المتين لجودة الهواء يجمع بين قياس الملوثات وبيانات الطقس والسياق الكيميائي، ولا يعتمد على مؤشر إجمالي وحده."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد انتشار الملوثات في الطبقة الحدية على تفسير تغير تركيب الغلاف الجوي وربط مصادر المواد وانتقالها وتحولها وإزالتها بالظروف الجوية."}]}'::jsonb,7100,50,'["شرح أساسيات انتشار الملوثات في الطبقة الحدية","تحليل أثر الطقس في التركيب الجوي","تقييم البيانات وحدود الاستنتاج"]'::jsonb,'التلوث الجوي والتطبيقات البيئية'),
('air-quality-meteorological-indexing','المؤشرات الجوية لجودة الهواء','الربط بين الطقس والتراكيز','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تجمع المؤشرات معلومات الملوثات في قيم سهلة التفسير وفق قواعد صحية وتنظيمية محددة، لكن المؤشر ليس بديلاً عن عرض الملوثات الفردية وظروف القياس. تتغير آثاره مع تعريف المؤشر والحدود المستخدمة."},{"type":"heading","text":"العوامل الجوية والكيميائية"},{"type":"text","text":"يتأثر المؤشرات الجوية لجودة الهواء بمصادر الانبعاث والنقل الأفقي والخلط الرأسي والاستقرار والرطوبة والإشعاع ودرجة الحرارة. ينبغي التمييز بين التركيز المقاس قرب السطح والكمية الموجودة في عمود الغلاف الجوي، وبين المادة الأولية والنواتج الثانوية."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد الملوث أو الجسيم ومصدر البيانات وطريقة القياس.","راجع المعايرة والوحدات وفترة المتوسط وأعلام الجودة.","اربط التغيرات الزمنية بالرياح وارتفاع الخلط والاستقرار.","افحص مؤشرات التحول الكيميائي والنقل والترسيب.","قارن بمحطات خلفية أو منتجات مستقلة قبل إسناد المصدر."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حلقة تلوث","text":"اجمع قياسات الملوثات والطقس خلال حلقة زمنية وطبق إطار المؤشرات الجوية لجودة الهواء. افصل أثر الانبعاثات عن أثر الطقس، ثم حدد ما يمكن إثباته من البيانات وما يحتاج إلى قياسات كيميائية إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح لماذا ينبغي إظهار الملوث المسيطر إلى جانب قيمة مؤشر جودة الهواء."},{"type":"heading","text":"قيود ومصادر خطأ"},{"type":"list","items":["استنتاج المصدر من تركيز ملوث واحد فقط.","تجاهل زمن المتوسط وموقع جهاز القياس.","الخلط بين التزامن الزمني والسببية الكيميائية.","إهمال الرطوبة وتأثيرها في القياسات البصرية.","تعميم نتائج محطة واحدة على منطقة واسعة."]},{"type":"callout","text":"التفسير المتين لجودة الهواء يجمع بين قياس الملوثات وبيانات الطقس والسياق الكيميائي، ولا يعتمد على مؤشر إجمالي وحده."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد المؤشرات الجوية لجودة الهواء على تفسير تغير تركيب الغلاف الجوي وربط مصادر المواد وانتقالها وتحولها وإزالتها بالظروف الجوية."}]}'::jsonb,7110,50,'["شرح أساسيات المؤشرات الجوية لجودة الهواء","تحليل أثر الطقس في التركيب الجوي","تقييم البيانات وحدود الاستنتاج"]'::jsonb,'التلوث الجوي والتطبيقات البيئية'),
('smoke-transport-and-injection-height','نقل الدخان وارتفاع حقنه','الأعمدة الحرارية والرياح العلوية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمكن لحرائق الغطاء النباتي أن تطلق دخاناً يرتفع إلى مستويات مختلفة بحسب شدة الحمل الحراري والاستقرار والرياح. يحدد ارتفاع الحقن مسار النقل بعيد المدى وفرص اختلاط الدخان بالطبقة الحدية."},{"type":"heading","text":"العوامل الجوية والكيميائية"},{"type":"text","text":"يتأثر نقل الدخان وارتفاع حقنه بمصادر الانبعاث والنقل الأفقي والخلط الرأسي والاستقرار والرطوبة والإشعاع ودرجة الحرارة. ينبغي التمييز بين التركيز المقاس قرب السطح والكمية الموجودة في عمود الغلاف الجوي، وبين المادة الأولية والنواتج الثانوية."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد الملوث أو الجسيم ومصدر البيانات وطريقة القياس.","راجع المعايرة والوحدات وفترة المتوسط وأعلام الجودة.","اربط التغيرات الزمنية بالرياح وارتفاع الخلط والاستقرار.","افحص مؤشرات التحول الكيميائي والنقل والترسيب.","قارن بمحطات خلفية أو منتجات مستقلة قبل إسناد المصدر."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حلقة تلوث","text":"اجمع قياسات الملوثات والطقس خلال حلقة زمنية وطبق إطار نقل الدخان وارتفاع حقنه. افصل أثر الانبعاثات عن أثر الطقس، ثم حدد ما يمكن إثباته من البيانات وما يحتاج إلى قياسات كيميائية إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن تأثير عمود دخان يبقى في الطبقة الحدية بآخر يصل إلى مستويات حرة أعلى."},{"type":"heading","text":"قيود ومصادر خطأ"},{"type":"list","items":["استنتاج المصدر من تركيز ملوث واحد فقط.","تجاهل زمن المتوسط وموقع جهاز القياس.","الخلط بين التزامن الزمني والسببية الكيميائية.","إهمال الرطوبة وتأثيرها في القياسات البصرية.","تعميم نتائج محطة واحدة على منطقة واسعة."]},{"type":"callout","text":"التفسير المتين لجودة الهواء يجمع بين قياس الملوثات وبيانات الطقس والسياق الكيميائي، ولا يعتمد على مؤشر إجمالي وحده."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد نقل الدخان وارتفاع حقنه على تفسير تغير تركيب الغلاف الجوي وربط 